function updateResearch(){if(panelTab!=='research')return;$('research-list').innerHTML=Object.keys(state.upgrades).map(type=>{const m=E.META[type],cost=E.upgradeCost(state,type),ready=cost&&Object.entries(cost).every(([v,n])=>(state.bank[v]||0)>=n),locked=!E.unlocked(state,type);return `<div class="research-row"><div class="research-icon" style="color:${m.color}">${m.icon}</div><div><h3>${m.name} <small>· tier ${state.upgrades[type]+1}/13</small></h3><p>Current: ${E.speed(state,type).toFixed(2)} /s ${cost?'→ '+E.speed({...state,upgrades:{...state.upgrades,[type]:state.upgrades[type]+1}},type).toFixed(2)+' /s':'· fully tuned'}</p>${cost?Object.entries(cost).map(([v,n])=>`<span class="cost ${(state.bank[v]||0)>=n?'enough':''}"><b>Number ${v}</b> · ${state.bank[v]||0} / ${n} banked · ${Math.max(0,n-(state.bank[v]||0))} more needed</span>`).join(''):''}</div><button data-upgrade="${type}" ${!ready||locked?'disabled':''}>${locked?'Locked':cost?'Upgrade':'Max'}</button>${state.career.vouchers&&cost&&!locked?`<button data-voucher="${type}">Use voucher (${state.career.vouchers})</button>`:''}</div>`}).join('');$('research-list').querySelectorAll('[data-voucher]').forEach(b=>b.onclick=()=>{if(obscured())return;if(E.useVoucher(state,b.dataset.voucher)){save();updateResearch();renderUI()}});$('research-list').querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{if(obscured())return;if(E.buyUpgrade(state,b.dataset.upgrade)){save();beep(660,.12);updateResearch();renderUI()}})}
function openBook(tab='contracts'){panelTab='book';openPanel('The dispatch book',`<div class="tabs"><button id="book-projects">Engineering projects</button><button data-tab="contracts" class="${tab==='contracts'?'current':''}">Commissions</button><button data-tab="deliveries" class="${tab==='deliveries'?'current':''}">Production ledger</button><button data-tab="planning" class="${tab==='planning'?'current':''}">Planning notes</button></div><div id="book-content"></div>`,'PRODUCTION');$('panel-body').querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>openBook(b.dataset.tab));$('book-projects').onclick=openProjects;const body=$('book-content');if(tab==='contracts'){body.innerHTML=`<div class="roadmap">${E.roadmap(state).map((c,i)=>`<div class="roadmap-card"><small>${i?'NEXT '+i:'CURRENT'}</small><b>${c.value.toLocaleString('en-US')}</b><span>${c.delivered} / ${c.count}</span><small>${esc(E.rewardText(c.reward))}</small></div>`).join('')}</div><p class="panel-note">All deliveries are retained. Produce upcoming targets early if you want. Finish 24 commissions to graduate; optional open commissions follow.</p>`+E.CONTRACTS.map(([v,n,t,h,r],i)=>`<div class="book-row ${i===state.level?'active':''}"><span class="num">${i<state.level?'✓':String(i+1).padStart(2,'0')}</span><strong>${Number(v).toLocaleString('en-US')}</strong><div class="details"><b>${t}</b><small>${Math.min(n,state.delivered[v]||0)} / ${n} delivered${r?' · '+E.rewardText(r):''}</small></div></div>`).join('');}
 if(tab==='deliveries'){const values=Object.keys(state.delivered).sort((a,b)=>state.delivered[b]-state.delivered[a]);body.innerHTML=`<p class="panel-note">Rates use the last 30 simulated seconds. Reservoirs and bottlenecks can make short samples uneven.</p><table><thead><tr><th>NUMBER</th><th>DELIVERED</th><th>BANK</th><th>PER SECOND</th></tr></thead><tbody>${values.length?values.map(v=>`<tr><td>${v}</td><td>${state.delivered[v]}</td><td>${state.bank[v]||0}</td><td>${E.rate(state,Number(v)).toFixed(2)}</td></tr>`).join(''):'<tr><td colspan="4">Your first delivery will appear here.</td></tr>'}</tbody></table><p class="panel-note">${state.stats.extracted} extracted · ${state.stats.processed} operations · ${state.stats.recycled} recycled</p>`;}
 if(tab==='planning')body.innerHTML=`<div class="help-grid"><div><h3>Reuse the middle.</h3><p>A line making 6 can feed an upgrade, make 12 with an adder, or make 18 with a multiplier. A junction distributes packets; it does not duplicate them.</p><h3>Work backwards.</h3><p>For 127, think 128 − 1. For 2025, think 45 × 45. For 99991, try 10^5 − 9. Building a reusable 10 stream makes decimal construction easier.</p></div><div><h3>Match your rates.</h3><p>Two input streams must keep up with every operator. If a belt carries 6/s and a machine processes 2/s, three parallel machines can use that belt. Check both inputs and the output.</p><h3>Drain both outputs.</h3><p>A divider produces Q and R. Connect a recycler to an unwanted remainder, even when it is zero. A blocked output stops the next operation.</p></div></div><p class="note">Current idea: ${esc(E.contract(state).hint)}</p>`;}
function openFinder(){openPanel('Find a starting number',`<p class="panel-note">Locate a deposit near the current view. Higher deposits unlock through the campaign. Building on a deposit does not consume it.</p><div class="tabs">${Array.from({length:9},(_,i)=>`<button data-find="${i+1}">${i+1}${i+1>E.maxExtract(state)?' · locked':''}</button>`).join('')}</div><button id="clear-find">Clear highlight</button><h3>Explore coordinates</h3><p class="panel-note">Travel anywhere; deposits are generated consistently from the world seed. H returns to Dispatch.</p><label class="field">X <input id="travel-x" type="number" value="${Math.round(state.camera.x)}" step="1"></label><label class="field">Y <input id="travel-y" type="number" value="${Math.round(state.camera.y)}" step="1"></label><button id="travel-go" class="primary">Travel</button>`,'SURVEY');$('panel-body').querySelectorAll('[data-find]').forEach(b=>b.onclick=()=>{const v=Number(b.dataset.find),p=E.nearest(state,v,state.camera.x,state.camera.y);if(p){state.camera.x=p.x;state.camera.y=p.y;searchNumber=v;cursor={x:p.x,y:p.y};closePanel();toast('Deposit '+v+(v>E.maxExtract(state)?' · not yet unlocked':''));}});$('clear-find').onclick=()=>{searchNumber=null;closePanel()};$('travel-go').onclick=()=>{const x=Number($('travel-x').value),y=Number($('travel-y').value);if(!Number.isSafeInteger(x)||!Number.isSafeInteger(y)||Math.abs(x)>E.WORLD-100||Math.abs(y)>E.WORLD-100){toast('Choose whole coordinates within the numeric safety range.');return}state.camera.x=x;state.camera.y=y;cursor={x,y};searchNumber=null;closePanel();save();toast('Exploring '+x+', '+y+' · H returns home');}}
function markerAt(p){const existing=state.markers.find(m=>m.x===p.x&&m.y===p.y);openPanel('Label this line',`<label class="field">A name for this part of the factory<input id="marker-text" type="text" maxlength="60" value="${esc(existing?.text||'')}"></label><div class="dialog-actions"><button class="primary" id="marker-save">Save marker</button>${existing?'<button id="marker-delete">Remove marker</button>':''}</div>`,'MAP NOTE');$('marker-save').onclick=()=>{if(obscured())return;const value=$('marker-text').value.trim();if(value){if(existing)existing.text=value;else if(state.markers.length<100)state.markers.push({x:p.x,y:p.y,text:value});save();closePanel()}};if(existing)$('marker-delete').onclick=()=>{state.markers=state.markers.filter(m=>m!==existing);save();closePanel()};$('marker-text').focus()}
function saveModule(){const bp=E.blueprint(state,[...selected]);if(!bp)return;openPanel('Keep a useful idea',`<p class="panel-note">Save these ${bp.nodes.length} pieces as a reusable module. Packets are not copied.</p><label class="field">Module name<input id="module-name" type="text" maxlength="40" value="Number line ${state.blueprints.length+1}"></label><button class="primary" id="module-save">Save module</button>`,'MODULE LIBRARY');$('module-save').onclick=()=>{if(obscured())return;if(state.blueprints.length>=20){toast('Library is full. Remove a module first.');return}bp.name=$('module-name').value.trim().slice(0,40)||'Module';state.blueprints.push(bp);save();closePanel();toast('Module saved. Find it in Workshop → Modules.')}}
function openModules(){openPanel('Built once. Used often.',`<p class="panel-note">Select pieces on the floor and choose Save module. Rotate a pasted module with R before placing. A paste is all-or-nothing if anything collides.</p><div class="modules">${state.blueprints.length?state.blueprints.map((bp,i)=>`<div class="module"><div><strong>${esc(bp.name)}</strong><small>${bp.nodes.length} factory pieces</small></div><button data-load="${i}">Place</button><button data-remove="${i}" aria-label="Delete ${esc(bp.name)}">×</button></div>`).join(''):'<p class="note">Your module library is ready for its first idea.</p>'}</div>`,'MODULE LIBRARY');$('panel-body').querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>{clipboard=E.copy(state.blueprints[+b.dataset.load]);closePanel();setTool('paste')});$('panel-body').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.blueprints.splice(+b.dataset.remove,1);save();openModules()})}
function download(data,name){const url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function changeMode(next,demo=false){save();mode=next;state=E.create(2147,next==='sandbox');blocked=false;rawBad=null;if(!demo){try{const raw=localStorage.getItem(saveKey());if(raw)state=E.decode(raw)}catch{blocked=true;try{rawBad=localStorage.getItem(saveKey())}catch{}}}else{
 E.place(state,'extractor',-9,-3);E.place(state,'extractor',-9,1);E.place(state,'add',-4,-3);E.drawBelt(state,E.beltPath(-8,-3,-5,-3));E.drawBelt(state,E.beltPath(-8,1,-5,-2));const corner=state.buildings.find(n=>n.x===-5&&n.y===-2);corner.dir=0;E.drawBelt(state,E.beltPath(-2,-3,-1,1));const end=state.buildings.find(n=>n.x===-1&&n.y===1);end.dir=0;E.place(state,'extractor',-9,5);E.drawBelt(state,E.beltPath(-8,5,0,5));E.drawBelt(state,E.beltPath(0,5,0,3));state.markers.push({x:-9,y:-5,text:'2 + 1 → 3'},{x:-9,y:7,text:'A steady stream of 1s'});}
 history=[];future=[];selected.clear();clipboard=null;paused=false;centerHub();save();closePanel();renderTools();setTool('inspect');}
function openMenu(){openPanel('Your workshop',`<div class="tabs"><button id="open-modules">Modules</button><button id="open-finder">Find deposits</button><button id="open-book">Dispatch book</button><button id="open-help">Field guide</button></div><p class="panel-note">${state.sandbox?'Sandbox':'Campaign'} · ${state.buildings.length} pieces · seed ${state.seed}. Autosaves stay in this browser. Export a file before changing browsers or clearing site data.</p>${blocked?'<p class="note error">The existing save could not be read. Its bytes have been preserved. Export them before choosing Replace unreadable save.</p><button id="export-bad">Export unreadable save</button><button id="recover-save">Replace unreadable save</button>':''}<div class="dialog-actions"><button id="export-save" class="primary">Export factory</button><button id="import-save">Import factory</button><button id="restore-backup">Restore last backup</button></div><label class="field"><input id="art-setting" type="checkbox" ${detailedArt?'checked':''}> Detailed Blender machinery (off = clean factory view)</label><label class="field"><input id="sound-setting" type="checkbox" ${sound?'checked':''}> Gentle interface sounds</label><label class="field"><input id="motion-setting" type="checkbox" ${reduced?'checked':''}> Reduce conveyor motion</label><label class="field"><input id="guide-setting" type="checkbox" ${showGuide?'checked':''}> Show the getting-started guide</label><div class="dialog-actions"><button id="switch-mode">Open ${state.sandbox?'campaign':'sandbox'}</button><button id="demo">Open working demonstration</button><button id="new-factory">New ${mode} factory</button></div><p class="panel-note">Original code, visuals and progression. Inspired by mathematical factory games. No external assets, tracking, downloads or purchases required.</p>`);$('open-modules').onclick=openModules;$('open-finder').onclick=openFinder;$('open-book').onclick=()=>openBook();$('open-help').onclick=openHelp;$('export-save').onclick=()=>download(E.encode(state),`numberworks-${mode}.json`);$('import-save').onclick=()=>$('import-file').click();$('restore-backup').onclick=()=>{try{const backup=E.decode(localStorage.getItem(saveKey()+'.backup'));confirmAction('Restore the backup?','This replaces the current layout and production with the last valid automatic backup.',()=>{state=backup;blocked=false;history=[];future=[];selected.clear();save();closePanel();renderTools()})}catch{toast('No valid backup is available.')}};$('art-setting').onchange=e=>{detailedArt=e.target.checked;try{localStorage.setItem('numberworks.detailedArt',detailedArt)}catch{}};$('sound-setting').onchange=e=>{sound=e.target.checked;try{localStorage.setItem('numberworks.sound',sound)}catch{}beep(600,.08)};$('motion-setting').onchange=e=>reduced=e.target.checked;$('guide-setting').onchange=e=>showGuide=e.target.checked;$('switch-mode').onclick=()=>changeMode(state.sandbox?'campaign':'sandbox');$('demo').onclick=()=>confirmAction('Open the demonstration?','This replaces only the sandbox slot with a working example. Your campaign stays.',()=>changeMode('sandbox',true));$('new-factory').onclick=()=>confirmAction('Start a new factory?','This clears only the current '+mode+' slot. Export a backup first if you want to keep it.',()=>{state=E.create(2147,mode==='sandbox');history=[];future=[];selected.clear();blocked=false;centerHub();save();closePanel();renderTools();setTool('extractor')});if(blocked){$('export-bad').onclick=()=>download(rawBad||'', 'numberworks-unreadable.json');$('recover-save').onclick=()=>confirmAction('Replace unreadable save?','The old bytes will be replaced by this session. Export them first if you want to keep them.',()=>{blocked=false;save();closePanel()})}}
$('import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5000000){toast('That file is too large.');return}try{const imported=E.decode(await file.text());confirmAction('Import this factory?',`Replace the ${imported.sandbox?'sandbox':'campaign'} slot with ${imported.buildings.length} pieces? Other games and the other slot stay.`,()=>{save();mode=imported.sandbox?'sandbox':'campaign';state=imported;blocked=false;history=[];future=[];selected.clear();save();closePanel();resize();renderTools();setTool('inspect')})}catch(e){toast('Import rejected: '+e.message)}};
function openHelp(){showGuide=true;renderUI();openPanel('A small field guide',`<div class="help-grid"><div><h3>1. Extract & connect</h3><p>Put an extractor on a numbered deposit. Its arrow sends packets onto an adjacent belt. Drag belts towards Dispatch; a preview shows their direction before release. Construction is free.</p><h3>2. Give numbers a purpose</h3><p>Operators occupy 2 × 2 tiles. Connect belts to amber A and B ports. Teal ports are outputs. Rotate with R. Inspect a stopped machine to see exactly what is missing.</p><h3>3. Build reusable lines</h3><p>Deliveries count toward the current and future commissions. Research spends the separate bank. Select, copy and rotate entire modules; junctions split supply rather than creating free copies.</p><h3>Ports & arithmetic</h3><p>A − B can be negative. Division rounds down and emits both a quotient and remainder (even zero). Drain both outputs. Power accepts exponents 0–31; results beyond ±999,999,999,999 stop safely.</p></div><div><h3>Keyboard & mouse</h3><p><kbd>WASD</kbd> / right-drag: pan<br>Wheel / <kbd>+</kbd> <kbd>−</kbd>: zoom<br><kbd>B</kbd> belt · <kbd>E</kbd> extractor<br><kbd>1–5</kbd> arithmetic tools<br><kbd>R</kbd> rotate · <kbd>F</kbd> belt bend<br><kbd>Alt</kbd> while starting a belt: reverse<br><kbd>V</kbd> select · <kbd>X</kbd> erase<br><kbd>Ctrl C / V / X</kbd> copy / paste / cut<br><kbd>Ctrl Z / Y</kbd> undo / redo construction<br><kbd>H</kbd> home · <kbd>G</kbd> goals · <kbd>U</kbd> research<br><kbd>Space</kbd> pause · <kbd>Esc</kbd> cancel<br>Arrow keys move the placement cursor; Enter places.</p><h3>Touch</h3><p>Choose a tool, then tap to place. Drag to draw belts or select a region. Choose Pan to move the view, or pinch to zoom. Rotate and Place buttons are below the floor. Workbench opens the inspector.</p></div></div><p class="note">Undo changes construction, not elapsed production or deliveries. Removing, rotating or flushing machines discards their in-flight packets. Hidden tabs pause; there is no offline production. Terrain generates as you explore, with no practical map edge. Only visible terrain is drawn. A numeric safety boundary of ±1 billion tiles and an 8,000-building simulation budget protect browser performance.</p><p class="panel-note">There is no failure timer. Graduate after 24 commissions, then continue open commissions or use the separate all-tools sandbox.</p>`,'HOW IT WORKS')}
function welcome(){openPanel('Build your first line',`<div class="welcome"><div><h3>Extract. Combine. Deliver.</h3><p>Start with one extractor and a conveyor. The guide highlights each step. Unlock arithmetic machines, choose engineering projects, and improve the lines you build.</p><div class="feature-line"><b>01</b> Extract & route</div><div class="feature-line"><b>02</b> Combine & automate</div><div class="feature-line"><b>03</b> Research & expand</div><div class="dialog-actions"><button id="start" class="primary">Start building →</button><button id="try-demo">See a working factory</button></div></div><div class="welcome-art"><svg viewBox="0 0 260 230" aria-label="Two number streams combine into a new number"><path d="M30 45h70v45h55M30 165h70v-45h55M205 105h30" fill="none" stroke="#748e77" stroke-width="15" stroke-linejoin="round"/><rect x="5" y="24" width="44" height="44" rx="10" fill="#dfb871"/><rect x="5" y="144" width="44" height="44" rx="10" fill="#dfb871"/><rect x="137" y="67" width="72" height="72" rx="13" fill="#80ad97"/><g fill="#f4f5df" font-family="monospace" text-anchor="middle"><text x="27" y="53" font-size="23">2</text><text x="27" y="173" font-size="23">3</text><text x="173" y="117" font-size="40">+</text></g><rect x="226" y="88" width="30" height="32" rx="5" fill="#f1d7a3"/><text x="241" y="111" text-anchor="middle" font-size="20" fill="#5a7158" font-family="monospace">5</text><text x="130" y="220" text-anchor="middle" font-size="9" letter-spacing="2" fill="#8ca07d">2 + 3 → 5</text></svg></div></div>`,'WELCOME TO NUMBERWORKS');$('start').onclick=()=>{closePanel();setTool('extractor');first=false;save()};$('try-demo').onclick=()=>{changeMode('sandbox',true);first=false};}
$('factory-rank').onclick=openProjects;$('career-goals').onclick=openProjects;$('project-pin').onclick=openProjects;$('guide-action').onclick=()=>{const l=E.lesson(state);if(!l)return;if(l.action==='research'){openResearch();return}if(l.action==='goals'){openBook();return}centerHub();state.camera.x=l.x+3;state.camera.y=l.y+1;cursor={x:l.x,y:l.y};dir=0;setTool(l.tool);if(l.machine&&l.tool==='inspect'){selected=new Set([l.machine]);renderUI(true)}toast('Highlighted on the floor · '+l.title)};
$('pause').onclick=()=>{if(obscured())return;paused=!paused;renderUI()};$('research').onclick=openResearch;$('goals').onclick=()=>openBook();$('menu').onclick=openMenu;$('help').onclick=openHelp;$('home').onclick=e=>{e.preventDefault();centerHub()};$('close-panel').onclick=closePanel;$('panel').addEventListener('cancel',()=>{panelTab='';drag=null;queueMicrotask(()=>canvas.focus())});$('cancel-confirm').onclick=()=>$('confirm-dialog').close();$('undo').onclick=undo;$('redo').onclick=redo;$('copy').onclick=()=>copySelected();$('cut').onclick=()=>copySelected(true);$('save-blueprint').onclick=saveModule;$('delete-selection').onclick=()=>edit(()=>{E.remove(state,[...selected]);selected.clear()});$('zoom-in').onclick=()=>zoom(1.2);$('zoom-out').onclick=()=>zoom(1/1.2);$('hub').onclick=centerHub;$('speed').onclick=()=>{simSpeed=simSpeed===1?2:simSpeed===2?4:1;renderUI()};$('dismiss-guide').onclick=()=>{showGuide=false;renderUI()};$('inspect-toggle').onclick=()=>$('inspector').classList.toggle('open');$('hide-inspector').onclick=()=>$('inspector').classList.remove('open');$('rotate-mobile').onclick=rotateTool;$('confirm-mobile').onclick=()=>placeAt(cursor);
function hide(){drag=null;pointers.clear();pinch=null;paused=true;save();renderUI();$('accept-confirm').disabled=true;}
document.addEventListener('visibilitychange',()=>{if(document.hidden)hide();else{$('accept-confirm').disabled=false;last=performance.now()}});window.addEventListener('message',e=>{if(e.source===parent&&e.origin===location.origin&&e.data?.type==='study-visibility'&&typeof e.data.visible==='boolean'){parentHidden=!e.data.visible;if(parentHidden)hide();else{$('accept-confirm').disabled=document.hidden;last=performance.now()}}});window.addEventListener('pagehide',save);window.addEventListener('resize',resize);
function frame(now){const elapsed=Math.min(.1,(now-last)/1000);last=now;if(!paused&&!busy()){accumulator+=elapsed*simSpeed;let steps=0;while(accumulator>=1/60&&steps++<24){E.step(state,1/60);accumulator-=1/60}saveClock+=elapsed;uiClock+=elapsed;celebrate=Math.max(0,celebrate-elapsed);if(state.events.length){const event=state.events.pop();state.events=[];toast((event.kind==='rank'?'Factory rank · ':event.kind==='project'?'Project complete · ':'Commission complete · ')+event.text);beep(780,.22);celebrate=2;renderTools();save();}if(saveClock>10)save();}else accumulator=0;if(uiClock>.25){uiClock=0;renderUI();if(panelTab==='research')updateResearch()}if(now>toastUntil)$('toast').classList.remove('visible');draw();requestAnimationFrame(frame)}
if(first||innerWidth<700&&state.buildings.length===0)centerHub();resize();renderTools();renderUI(true);requestAnimationFrame(frame);if(first&&!blocked)welcome();if(blocked)toast('Existing save could not be read. It is preserved; open Workshop for recovery.');

function openProjects(){const active=state.career.active,r=E.rankProgress(state);const rankCard=r?`<section class="rank-card"><h3>Next factory rank: ${r.name}</h3><p>${state.stats.delivered} / ${r.total} total deliveries · ${Math.min(r.streamsReady,r.streams)} / ${r.streams} balanced streams</p><p>Deliver ${r.streams} ${r.streams===1?"number":"different numbers"}, each at least ${r.minimum}, at ${r.rate}/s each measured over 30 running seconds. Keep the lines running together.</p><b>Reward: +15% base speed to every machine and one research voucher.</b><p>Current permanent boost: +${(state.career.rank||0)*15}%. No reset and no deadline.</p></section>`:'<section class="rank-card"><h3>Number empire · all ranks earned</h3><p>Your entire factory runs at +75% base speed. Keep optimizing engineering project records.</p></section>'; openPanel('Engineering projects',`<p class="panel-note">Commissions unlock machines. Projects test the factory you build with them. Choose a project; new deliveries count toward it while commissions continue. There is no deadline.</p>${rankCard}<div class="career-summary"><b>${Object.keys(state.career.completed).length} / ${E.PROJECTS.length} projects completed</b><span>${state.career.vouchers} research vouchers</span></div><div class="project-list">${E.PROJECTS.map(p=>{const done=state.career.completed[p.id],running=active?.id===p.id,locked=!state.sandbox&&state.level<p.unlock;return `<article class="project-card ${running?'running':''}"><div class="eyebrow">${done?'✓ COMPLETED':running?'IN PROGRESS':locked?'UNLOCKS AFTER COMMISSION '+p.unlock:'AVAILABLE'}</div><h3>${p.name}</h3><p>${p.brief}</p><div class="project-needs">${Object.entries(p.needs).map(([v,n])=>`<span><b>${v}</b> ${running?Math.min(n,active.delivered[v]||0):0}/${n}</span>`).join('')}</div>${done?`<p class="record">Best: ${done.seconds.toFixed(1)}s · fewest pieces: ${done.pieces} · fewest operators: ${done.ops}<br>Piece and operator records use peak counts during the run. These are separate personal records. Replay earns no extra vouchers.</p>`:'<p class="record">First completion: 2 research vouchers. Each buys one available speed upgrade.</p>'}<button data-project="${p.id}" ${locked||active?'disabled':''}>${running?'Running':done?'Replay project':'Start project'}</button></article>`}).join('')}</div><div class="dialog-actions"><button id="project-commissions">View commissions</button>${active?'<button id="project-cancel">Cancel current project</button>':''}</div>`,'LONG-TERM GOALS');$('panel-body').querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{if(obscured())return;if(E.startProject(state,b.dataset.project)){save();closePanel();toast('Project started. New deliveries now count.')}});$('project-commissions').onclick=()=>openBook();if(active)$('project-cancel').onclick=()=>{if(obscured())return;E.cancelProject(state);save();openProjects()};}
